INSERT INTO products (asin, slug, name, brand, model_number, type_cafetiere, description_long, price_eur, currency, rating, ratings_total, bestsellers_rank, bestsellers_cat, amazons_choice, color, material, capacity_l, dimensions_cm, weight_kg, main_image_url, images_json, specifications_json, features_json, top_reviews_json, summary_avis, status) VALUES ('B077ZK2K9D', 'melitta-melitta-barista-t-smart-noire-machine-a-cafe-a-grains-avec-broyeur-et-reservoir-a-lait-systeme-one-touch-mode-1-a-2-tasses-cafetiere-connectee-ecran-couleur-tft-f850-102-no', 'Melitta Barista T Smart Noire, Machine à Café à Grains avec Broyeur et Réservoir à Lait, Système One Touch, Mode 1 à 2 Tasses, Cafetière Connectée, Écran Couleur TFT, F850-102 Noir Machine à Café', 'Melitta', 'F85/0-102', 'espresso_broyeur_auto', 'Description du produit Machine à café broyeur Barista T Smart de Melitta — Préparez votre café ou latte depuis votre smartphone ! La machine à expresso Barista T Smart de Melitta permet de préparer deux tasses de café simultanément. Mesurant seulement 20cm de large, la cafetière à grain se glisse dans toutes les cuisines. Elle comprend un broyeur à grains silencieux qui moud ces derniers rapidement, tout en l''humidifiant légèrement afin de développer les arômes et de vous offrir un café riche. Cette machine à café automatique permet de choisir parmi 3 niveaux d''intensité, du plus doux au corsé, ainsi que la quantité de café désiré, allant de 30 ml à 220 ml. La fonction One Touch permet de préparer cafés et lattes en une quelques secondes. Chaque café dégusté sera parfaitement à votre goût ! Fondée il y a plus d''un siècle par l''inventrice du filtre à café Melitta Bentz, Melitta est une entreprise Allemande qui a développé une véritable expertise dans la préparation du café; présente dans plus de 40 pays, cette entreprise familiale est reconnue à travers le monde pour son expertise du café : du grain à la tasse. Melitta vous propose une gamme complète de produits indispensables à la préparation d''un café d''exception. Melitta® a été élue « Meilleure satisfaction client » en 2024 par le Jury du Prix "Plus X Award" sur la catégorie des machines automatiques avec broyeur. Les caractéristiques de cette machine à café automatique : Machine à café broyeur Barista T Smart Connectée avec Réservoir à lait Mode 1 et 2 tasses 3 intensités de café Système d''extraction des arômes Bec d''écoulement du café réglable en hauteur Application Melitta Connect pour préparer son café depuis son smartphone Réservoir à eau : 1,8 L ; Réservoir à grains 2x135g (270) Longueur du câble : 1 m Contenu du coffret Melitta Barista TS Smart Noire F 850-102', 839.1, 'EUR', 4.1, 1486, 184, 'Machines à café automatiques', 1, 'Noir', 'Acier inoxydable', 1.8, '25,9P x 46,7l x 37,2H centimètres', NULL, 'https://m.media-amazon.com/images/I/718Rom+31YL.jpg', '[{"link": "https://m.media-amazon.com/images/I/41+dzggoElL._AC_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61307qf1pBL._AC_SL1500_.jpg"}, {"link": "https://m.media-amazon.com/images/I/418gGT9EpRL._AC_.jpg"}, {"link": "https://m.media-amazon.com/images/I/51a0U01EmQL._AC_SL1464_.jpg"}, {"link": "https://m.media-amazon.com/images/I/51t-BcBIBfL._AC_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61qdPxkAEQL._AC_SL1500_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61fb-TJ2ZFL._AC_SL1344_.jpg"}]', '[{"name": "Marque", "value": "Melitta"}, {"name": "Capacité", "value": "1,8 Litres"}, {"name": "Couleur", "value": "Noir"}, {"name": "Dimensions du produit", "value": "25,9P x 46,7l x 37,2H centimètres"}, {"name": "Caractéristique spéciale", "value": "Poids du produit en kilogrammes: 11.28, Pression de fonctionnement (barre): 15"}, {"name": "Type de cafetière", "value": "Machine à espresso"}, {"name": "Matériau", "value": "Acier inoxydable"}, {"name": "Style", "value": "Machine à Café"}, {"name": "Usages spécifiques pour le produit", "value": "Espresso, Lungo, Cappuccino, Cafe Creme, Latte Macchiato"}, {"name": "Usages recommandés pour le produit", "value": "Voyage"}, {"name": "Caractéristiques spéciales", "value": "Poids du produit en kilogrammes: 11.28, Pression de fonctionnement (barre): 15"}, {"name": "Usages particuliers du produit", "value": "Espresso, Lungo, Cappuccino, Cafe Creme, Latte Macchiato"}, {"name": "Mode de fonctionnement", "value": "Entièrement automatique"}, {"name": "Puissance", "value": "1450 Watts"}, {"name": "Tension", "value": "220.0"}, {"name": "Entrée par interface homme-machine", "value": "Écran tactile"}, {"name": "Type d’affichage", "value": "Écran couleur TFT, Touch & Slide"}, {"name": "Type de café", "value": "coffee_beans"}, {"name": "Source d’alimentation", "value": "Électrique filaire"}, {"name": "Type de filtre", "value": "Réutilisable"}, {"name": "Dimensions de l''article P x L x H", "value": "25,9P x 46,7l x 37,2H centimètres"}, {"name": "Poids de l''article", "value": "11,28 Kilogrammes"}, {"name": "Nombre d’articles dans l''unité vendue au client", "value": "1"}, {"name": "Finitions extérieures", "value": "Acier inoxydable"}, {"name": "L''article est-il lavable au lave-vaisselle ?", "value": "Non"}, {"name": "Pays d’origine", "value": "Portugal"}, {"name": "Composants inclus", "value": "Chambres de filtration, Chauffe-tasse, Système de mousse de lait, Égouttoir en acier inoxydable"}, {"name": "Nom du modèle", "value": "caffeo barista ts"}, {"name": "Numéro du modèle", "value": "F850-102"}, {"name": "Code article international", "value": "04006508217830"}, {"name": "Fabricant", "value": "Melitta"}, {"name": "Description de la garantie", "value": "2 ans de garantie."}, {"name": "Référence de pièce", "value": "F85/0-102"}, {"name": "Nom du type du produit", "value": "Cafetière expresso automatique"}, {"name": "Classement des meilleures ventes d''Amazon", "value": "343305 en Cuisine et Maison (Voir les 100 premiers en Cuisine et Maison) 184 en Machines à café automatiques"}, {"name": "ASIN", "value": "B077ZK2K9D"}, {"name": "Moyenne des commentaires client", "value": "4,1    4,1 sur 5 étoiles         (1 486)           4,1 sur 5 étoiles"}]', '["Mode Favoris — La cafetière à grain permet de mémoriser les boissons de 4 utilisateurs différents. Elle comprend également 18 recettes de boissons caféinées ou lactées préenregistrées", "Melitta Connect — Grâce à l’application connectez votre machine et gérez de nombreuses fonctionnalités depuis votre smartphone : personnalisation des boissons, entretien de la machine à café", "Double Réservoir à grains — La cafetière connectée possède une double réservoir de capacité totale 270g pour les grains et permet de choisir manuellement le type de grains pour chaque tasse", "One Touch — La fonction One Touch permet de préparer un expresso, café long, cappuccino, latte macchiato, mousse de lait ou de l''eau chaude d''une simple pression", "Durable — Un témoin lumineux vous indique lorsqu''il est temps de détartrer votre machine à expresso et latte Melitta Solo pour prolonger sa durée de vie et préserver les saveurs du café", "Entretien Minime — La technologie de la cartouche filtrante Pro Aqua permet de réaliser un seul détartrage de la machine à café automatique par an sous réserve de la changer tous les 2 mois", "Application Melitta Companion — Téléchargez l''application et retrouvez un guide interactif avec des conseils, des astuces, des tutoriels illustrés et d''autres fonctions pratiques pour utiliser et entretenir votre machine à expresso automatique", "Contenu — 1x Melitta Barista T Smart avec Réservoir à Lait, 1 x tuyau à lait, 1 x Long tuyau à lait - Dimensions : 259 x 372 x 467 mm; poids : 10,6 kg", "La machine est réparable et dispose de nombreuses pièces de rechange; les pièces détachées sont disponibles 10 ans"]', '[{"rating": 50, "title": "Impressionnante...", "body": "J''avoue avoir un peu hésité, après lecture des avis très divergents sur ce produit. J''ai donc sauté sur une \\"super offre\\" et plongé.Craintes fort probablement infondées.J''ai préféré attendre deux mois avant de rédiger mon commentaire.Une fois correctement réglée et surtout une fois trouvés les grains adéquats selon votre goût (il m''en aura fallu quatre ou cinq différents), les résultats sont excellents, la machine est simple d''emploi et avertit très clairement lors des (fréquentes!) interventions d''entretien.Je n''ai rencontré aucun problème avec l''application Bluetooth, bien conçue. Je m''en sers à environ 9 mètres de la machine, tous les matins (iOS).Minimes bémols:- la machine est assez lente. Cela peut déranger les anciens utilisateurs de machines à capsules, surtout au début.- la consommation d''eau tient du délire. Je ne vois pas d''autre mot. Cela rend l''usage de cartouches de filtration quasi obligatoire. Elles ne sont pas gratuites...Enfin on peut certes regretter qu''il soit possible de programmer l''extinction... mais pas l''allumage! Un petit effort, Melitta!", "date": "2022-10-22T00:00:00.000Z", "helpful_votes": 11, "verified_purchase": true}, {"rating": 50, "title": "Barista….", "body": "Très content de cet achat en reconditionnement.La machine fait le job depuis plusieurs mois.L’application sur téléphone ou tablette que je pensais être gadget, s’avère fonctionnelle et utile pour faire des recettes particulières ou doser les latte machiatto. On peut également y régler les paramètres habituels des favoris.Je ne regrette vraiment pas.", "date": "2024-12-07T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 10, "title": "hs après garantie", "body": "Très bonne machine, mais HS au bout de 2 ans et 4 mois juste après la garantie.le café coule derrière la machine et ne passe plus par les buses (tous les entretiens ont été réalisés en temps et en heure pourtant).", "date": "2023-05-15T00:00:00.000Z", "helpful_votes": 6, "verified_purchase": true}, {"rating": 50, "title": "J''adore!!!", "body": "J''adore !!! Elle réelle plaisir de tous les jours. On peut créer différents profils suivants les utilisateurs. Chacun choisit son Grain et fait ses recettes. Peu bruyante, je m''en sers tôt le matin et je ne réveille pas mes enfants.Tous les amis veulent la même.Application vraiment facile a prendre en main.Bref je suis très heureux de mon achat.", "date": "2025-08-21T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 40, "title": "Bon café, écran limité, 2 bacs grains", "body": "Acheté surtout pour le double bac grains (+ trappe à moulu) cette machine fait du très bon café... Mais  elle manque d''ergonomie pour les paramétrages des boissons. L''écran est petit, pas de grande qualité.Du coup c''est assez long pour définir les boissons de chacun.Surtout que la mise en mémoire dans my coffre s''avère aléatoire. Du moins pour ma machine.Bien pour le double bac, la qualité des boissons mais pas une grande facilité d''utilisation. Il faut dire que je viens d''une saeco avec écran très très facilement paramétrable. Mais sans double bac. A ces tarifs il faut choisir....", "date": "2023-04-06T00:00:00.000Z", "helpful_votes": 7, "verified_purchase": true}, {"rating": 50, "title": "Parfait!!", "body": "Je recommande cette machine, tres facile d utilisation, elle comporte 2 bacs a grains et nous pouvons aussi nous faire un cafe a partir de cafe moulu grace a un compartiment dedie à cela,  donc il est possible d utiliser 3 cafes differents en meme temps ce qui est tres pratique!", "date": "2021-03-30T00:00:00.000Z", "helpful_votes": 6, "verified_purchase": true}, {"rating": 50, "title": "Quel silence le top", "body": "Je recherchais vraiment le premier critère le bruit car Mme ce fait un café dans la nuit avant d''aller au travail et la au bout de 5 a 6 machines c''est la rolls pour moi, de plus j''ai appelé le service client de la marque pour me faire assister pour le paramétrage vous pouvez paramétrer plusieurs personnes et différents goûts plus ou moins fort le top la pompe quand elle rempli le café et plus bruyante que le broyeur incroyable le plus les cappuccino au top et mousse de lait ou lait chaud également voilà j''espère avoir détaillé au max", "date": "2022-10-10T00:00:00.000Z", "helpful_votes": 6, "verified_purchase": true}, {"rating": 20, "title": "Décevant", "body": "En panne à peine 7 mois d’utilisationVu le prix je trouve ceci inconcevableJe suis déçu", "date": "2021-08-30T00:00:00.000Z", "helpful_votes": 8, "verified_purchase": true}, {"rating": 50, "title": "Super ekspres", "body": "Świetny ekspres. Młynek metalowy który mieli do końca i zostaje pusty. Dwa pojemniki na kawę. Dużo ustawień i możliwości personalizacji kawy.", "date": "2024-05-25T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 50, "title": "Great Bean To Cup, one definitely to consider", "body": "Firstly, forget about the Bluetooth connectivity as this is an unreliable gimmick, but the Melitta App is highly useful for the maintenance and cleaning of the machine. Each part of the cleaning process is explained in the simplest way, a must have if trying to see the instructions on the machines screen is hard for you.Ok, on to the machine itself.Unpacking the machine is easy enough, but you do need to read the instructions carefully to ensure you have the hardness of your water and other information as and when needed.On first use I did an extra 2 coffees to flush the machine before actually drinking what it makes to ensure that it is only coffee you’ll be drinking and not lubricants.For drink preparation the machine can make 4 coffee variations from the front panel, but there are many more available from the menu system on the machine. The ability to save your favourites by person is useful to a certain extent and is extensive in the options for each coffee type but is limited to 1 setting per person per coffee option. To use a mycoffee option, you first press the  mycoffee icon then select cappuccino or latte and the machine starts straight away. I mostly use this due to a set coffee cup size and bean settings for latte and cappuccinos.The grinder is not silent but it is quiet enough not to be annoying, the bean hoppers hold enough for 15 - 20 cups in a single coffee dose setting and the machine is conservative in warning you about the hopper being empty and on swapping brands or strengths you do get a mix of beans for a couple of cups.As far as cleaning, the machine rinses itself on startup and shutdown and after each brew it asks to easy clean which sterilises the milk tube and milk system.The biggest thing that you do need to do every day is to empty the drip tray, I find this fills up after only a few cups have been made, else water will spill over and onto your counter top.For the cleaning of the machine and brew components it is easy to do and I do it every 10 to 12 days, it says a weeks interval but the machine doesn’t get that dirty inside.My conclusion with owning the Melitta Barista TS Smart is that if coffee is an important treat that you want to enjoy at home, this is the Bean to Cup machine for you. I am very pleased with the speed of warm up to coffee production is mere seconds and the taste of the coffee it produces. The coffee is hot enough to drink shortly after being made but hot enough not to go cold straight away.The cost and maintenance needed to actually own one of these machines should be considered, as pod machines can give close to bean to cup performance as a better price point. But this machine is a good balance of value for money and the production of great coffee at home.", "date": "2019-07-21T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}]', 'J''avoue avoir un peu hésité, après lecture des avis très divergents sur ce produit. J''ai donc sauté sur une "super offre" et plongé.Craintes fort probablement infondées.J''ai préféré attendre deux mois avant de rédiger mon commentaire.Une fois correctement réglée et surtout une fo | En panne à peine 7 mois d’utilisationVu le prix je trouve ceci inconcevableJe suis déçu | Acheté surtout pour le double bac grains (+ trappe à moulu) cette machine fait du très bon café... Mais  elle manque d''ergonomie pour les paramétrages des boissons. L''écran est petit, pas de grande qualité.Du coup c''est assez long pour définir les boissons de chacun.Surtout que l', 'published') ON DUPLICATE KEY UPDATE name=VALUES(name), price_eur=VALUES(price_eur), rating=VALUES(rating), ratings_total=VALUES(ratings_total), bestsellers_rank=VALUES(bestsellers_rank), main_image_url=VALUES(main_image_url), images_json=VALUES(images_json), top_reviews_json=VALUES(top_reviews_json), summary_avis=VALUES(summary_avis), updated_at=NOW();
INSERT INTO products (asin, slug, name, brand, model_number, type_cafetiere, description_long, price_eur, currency, rating, ratings_total, bestsellers_rank, bestsellers_cat, amazons_choice, color, material, capacity_l, dimensions_cm, weight_kg, main_image_url, images_json, specifications_json, features_json, top_reviews_json, summary_avis, status) VALUES ('B07GGZBRZX', 'de-longhi-de-longhi-dinamica-plus-ecam-370-95-t-machine-a-cafe-grain-avec-systeme-lait-cappuccino-et-espresso-ecran-tactile-tft-de-3-5-et-controle-via-application-fonction-carafe-a', 'De''Longhi Dinamica Plus ECAM 370.95.T, Machine a Cafe Grain avec Système Lait, Cappuccino et Espresso, Écran Tactile TFT de 3.5" et Contrôle via Application, Fonction Carafe à Café, 1450W, Titan Platine LatteCrema + TFT + commande par application. Unique', 'De''Longhi', 'ECAM 370.95.T', 'espresso_broyeur_auto', 'Description du produit Cappuccino crémeux, espresso fort ou latte macchiato parfait avec une mousse de lait particulièrement crémeuse - préparez votre café préféré en appuyant simplement sur un bouton via l''écran tactile ou l''application. En appuyant sur un seul bouton, vous pouvez préparer jusqu''à 6 tasses de café directement dans une cafetière avec la fonction de carafe à café. Le degré de mouture du moulin conique à 13 niveaux peut être ajusté manuellement selon vos préférences et le type de café. 5 forces de café préréglées offrent du café de très doux à très fort. Grâce au système breveté de carafe à lait, vous obtenez une mousse de lait parfaite pour chaque boisson. Et le meilleur : le nettoyage se fait automatiquement avec un bouton rotatif. De plus, les composants de la carafe à lait peuvent être placés dans le lave-vaisselle. Au fait : le bloc thermique De''Longhi chauffe rapidement l''eau à la température parfaite. Seule la quantité d''eau nécessaire pour la boisson est chauffée. Grâce aux deux systèmes de chauffage, le café et le lait peuvent être portés à des températures différentes en même temps. Le produit possède les caractéristiques suivantes : » Dimensions : 23,6 x 42,9 x 34,8 cm » Réservoir à grains : 300 g (+ compartiment pour la poudre de café) » Écran : écran tactile TFT de 3,5 pouces » Moulin conique extra silencieux (13 niveaux) : réglage individuel de la mouture » Double système de chauffage pour une préparation rapide » Réservoir d''eau : 1,8 L, amovible à l''avant Contenu du coffret Machine à café automatique', NULL, 'EUR', 4.4, 2653, 320, 'Machines à café automatiques', 1, 'Platine', 'Acier inoxydable, Plastique', 1.8, '9,3P x 13,7l x 16,9H centimètres', NULL, 'https://m.media-amazon.com/images/I/61TL5lRvWrL.jpg', '[{"link": "https://m.media-amazon.com/images/I/71Z+TedFksL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/71w5blUWWXL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/71hNYr1kQQL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/6187ZWS7ByL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61cmkj0oizL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/7121XzbaWeL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61Ex0cJIm+L._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61tb+zugqFL._AC_SL1499_.jpg"}]', '[{"name": "Marque", "value": "De''Longhi"}, {"name": "Capacité", "value": "1,8 Litres"}, {"name": "Couleur", "value": "Platine"}, {"name": "Dimensions du produit", "value": "9,3P x 13,7l x 16,9H centimètres"}, {"name": "Caractéristique spéciale", "value": "Hauteur de verseur de café réglable; Paramètres réglables moulin; Type d''écran: TFT; Broyeur intégré; Fabrication de caffe crema; Fabrication de capucccino; Type d''entrée à café: Coffee beans; Fabrication de latte macchiato; Réservoir de café: Cup Voir plus"}, {"name": "Type de cafetière", "value": "Machine à espresso"}, {"name": "Matériau", "value": "Acier inoxydable, Plastique"}, {"name": "Style", "value": "LatteCrema + TFT + commande par application."}, {"name": "Usages spécifiques pour le produit", "value": "cup_warmer, integrated_coffee_grinder, milk_frother, thermal, water_filter"}, {"name": "Usages recommandés pour le produit", "value": "Voyage"}, {"name": "Caractéristiques spéciales", "value": "Hauteur de verseur de café réglable; Paramètres réglables moulin; Type d''écran: TFT; Broyeur intégré; Fabrication de caffe crema; Fabrication de capucccino; Type d''entrée à café: Coffee beans; Fabrication de latte macchiato; Réservoir de café: Cup"}, {"name": "Usages particuliers du produit", "value": "cup_warmer, integrated_coffee_grinder, milk_frother, thermal, water_filter"}, {"name": "Mode de fonctionnement", "value": "Entièrement automatique"}, {"name": "Puissance", "value": "1450 Watts"}, {"name": "Tension", "value": "230 Volts"}, {"name": "Entrée par interface homme-machine", "value": "Pavé tactile, Écran tactile"}, {"name": "Type de café", "value": "café (grains et moulu)"}, {"name": "Source d’alimentation", "value": "AC"}, {"name": "Type de filtre", "value": "Réutilisable"}, {"name": "Dimensions de l''article P x L x H", "value": "9,3P x 13,7l x 16,9H centimètres"}, {"name": "Poids de l''article", "value": "20,94 Livres"}, {"name": "Nombre d’articles dans l''unité vendue au client", "value": "1"}, {"name": "Unité de comptage", "value": "1.0 unité"}, {"name": "Finitions extérieures", "value": "Inoxydable"}, {"name": "L''article est-il lavable au lave-vaisselle ?", "value": "Non"}, {"name": "Composants inclus", "value": "aucune"}, {"name": "Nom du modèle", "value": "Dinamica Plus"}, {"name": "Numéro du modèle", "value": "370.95T"}, {"name": "Type d''Emballage", "value": "emballage traditionnel"}, {"name": "Année de fabrication", "value": "2023"}, {"name": "Code article international", "value": "08004399332904"}, {"name": "Fabricant", "value": "DELONGHI"}, {"name": "Description de la garantie", "value": "2 year manufacturer."}, {"name": "Référence de pièce", "value": "ECAM 370.95.T"}, {"name": "Nom du type du produit", "value": "Cafetière automatique"}, {"name": "Classement des meilleures ventes d''Amazon", "value": "558792 en Cuisine et Maison (Voir les 100 premiers en Cuisine et Maison) 320 en Machines à café automatiques"}, {"name": "ASIN", "value": "B07GGZBRZX"}, {"name": "Moyenne des commentaires client", "value": "4,4    4,4 sur 5 étoiles         (2 653)           4,4 sur 5 étoiles"}, {"name": "Disponibilité de pièces détachées", "value": "10 Ans"}]', '["UTILISATION FACILE : Grand écran couleur TFT et un grand nombre de recettes café en un clic", "LATTECREMA-SYSTEM : Système de carafe à lait breveté pour une mousse de lait particulièrement crémeuse et onctueuse pour le cappuccino parfait - le nettoyage se fait automatiquement", "MOULIN DE HAUTE QUALITÉ : Le moulin conique à 13 niveaux peut être réglé individuellement, il peut contenir 200 g de grains de café dans le réservoir - la machine automatique convient également à l''utilisation de café moulu", "NETTOYAGE FACILE : L''infuseur compact est peu exigeant en entretien, peut être entièrement retiré de la machine à café, ce qui permet un nettoyage facile de l''intérieur de la machine", "Fonction carafe : Si vous attendez des invités, vous n''avez pas besoin de passer au café filtre - la fonction de carafe à café permet une préparation sans stress de jusqu''à 6 tasses de café en appuyant simplement sur un bouton"]', '[{"rating": 50, "title": "Machine esthétique et complète", "body": "C''est une super machine à café avec broyeur intégré. L''utilisation est extrêmement simple grâce à l''écran tactile, tous les réglages tombent sous le sens. Possibilité de faire une douzaine de boissons, notamment des lactées avec le système LatteCrema dont l''efficacité n''est plus à démontrer. L''intensité (quantité de café), le volume et la température des boissons sont réglables. Le bac à marc peut recevoir 14 marcs. Tous les éléments se nettoient aisément et on a même accès au bloc d''extraction. RAS. Seul bémol ça prend un peu les traces de doigt donc pensez à une microfibre à proximité ;)", "date": "2023-01-14T00:00:00.000Z", "helpful_votes": 3, "verified_purchase": true}, {"rating": 50, "title": "Excellente cafetière ++++++++", "body": "J''en suis ravi, j''avais auparavant une Jura Ena 9, qui me faisait un bon café, mais aucune comparaison avec celle ci.Le café est plus chaud (température réglable), avec un vrai goût d''expresso, une belle mousse. Les possibilités sont énormes, et très judicieuses, telle la carafe de café, le café long, double etc... Et, évidement les cappuccino et autres.Leur fabrication est extrêmement facile, et ils sont excellents, le nettoyage est très facile également, la fonction avec lait sur la Jura Ena 8 était fastidieuse, car il fallait tout de suite rincer le système, ce qui est normal, mais ça demandait tellement de manipulations, qu''on a vite abandonné.Ca demande du temps si on veut paramétrer parfaitement la cafetière, il y a tellement de possibilités, qu''il faut vraiment potasser le mode d''emploi, mais on peut s''amuser tout de suite quand même. Mais ça peut-être compliqué pour les anti geek. En tout cas tout le monde est hyper enthousiaste à la maison. Machine recommandée ++++++++++++++", "date": "2019-05-05T00:00:00.000Z", "helpful_votes": 43, "verified_purchase": true}, {"rating": 50, "title": "Machine extraordinaire", "body": "C''est ma première machine à broyeur, et... elle est extraordinaire. Facile à utiliser, café excellent (finis les nesspresso et vertuo), un capuccino fait en appuyant sur une seule touche... Je n''ai pas encore fait le tour de toutes les possibilités tellement il y en a.En comparant avec le site du constructeur, c''est exactement, vraiment exactement la même machine que la référence DINAMICA PLUS feb 3795t, qu''on peut voir facilement dans des magasins d''électro ménager, mais plus chère.Attention toutefois aux vendeurs marketplace de ce produit : certains affichent un prix fantaisiste et non réaliste (500€!) sans livraison prime... et qui annulent les commandes.", "date": "2021-10-08T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 40, "title": "Et le café fut!", "body": "J''ai mis du temps avant de choisir cette machine et je ne suis pas déçu.Reçu rapidement. Très bien emballée, la machine parait solide et bien pensée.Elle prend de la place sur un plan de travail en profondeur. Moins large qu''un micro onde.Je passerais sur l''application smartphone inutile pour ma part. Je ne vois pas l''intérêt de faire un café à distance à moins d''avoir un commis à côté de la machine pour mettre la bonne tasse...encore faut-il qu''il devine ce que l''on va prendre...Autre point négatif, le support métallique qui accueille les tasses. Il se raye très vite malgré les précautions d''usage.Passé cela, c''est parfait. Je n''ai pas poussé à fond les réglages et me suis contenté d''un choix \\"entre-deux\\".Le café est agréable en bouche et en goût. Maintenant, la machine ne rendra pas formidable un café bas de gamme. Les arômes des cafés particuliers (café de noël par exemple) sont parfaitement reproduits.J''apprécie pouvoir mémoriser la taille, la force et la température de mon café pour une utilisation rapide.Pour les invités, le réglage est rapide.Capacité de 250gr en grain pour le contenant.Réservoir d''eau tout à fait correct. Toutefois, je trouve que la consommation d''eau est importante du fait que la machine nettoie le gicleur au démarrage et à l''arrêt.Mes enfants apprécient se faire un chocolat chaud. C''est rapide et facile. La température aurait pu être plus chaude.Le nettoyage est simple et pratique. Les composants paraissent de qualité et semblent solides. A voir dans le temps.", "date": "2022-02-13T00:00:00.000Z", "helpful_votes": 20, "verified_purchase": true}, {"rating": 50, "title": "Au Top w!", "body": "Top qualité !", "date": "2026-02-10T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 10, "title": "cafetière acheté sur amazon second main", "body": "Bonjour. Je suis un très bon client Chez Amazon et je me suis dit pourquoi pas acheter La cafetière sur Amazon seconde main. De plus, j''ai lu que les produits seconde main étaient très bien vérifiés.Bref, je reçois le produit qui était déjà très sale et après un bon coup d''éponge le voila comme neuf.Super content de mon achat, je me fais un café et l''horreur, la cafetière fuit de partout, le bloc est fissuré. En conclusion, on m''a vendu un produit qui n''a pas été vérifié qu''un client a dû renvoyer quelques jours après son achat (il y avait un peu près 100 cafés qui avaient été faits dessus) donc si je comprends le principe du seconde main, c''est de ventes les produits défectueux que les personnes renvoient chez amazon.Là honnêtement, c''est quand même de l''escroquerieen plus j''adore acheter chez eux, mais seconde main s''est finij''attends un geste commercial… à suivre", "date": "2023-08-31T00:00:00.000Z", "helpful_votes": 7, "verified_purchase": true}, {"rating": 50, "title": "très bon haut de gamme", "body": "c''est ma deuxième delonghi , j''était très comptent de ma première délonghi (entré de gamme) met la je suis dans la cour des grand avec se modèle connecté ,café efficace fait moins de bruit que mon ancienne machine de plus je les acheté sur amazon warehouse ( occasion retour client )pour seulement 255€ il y avait marquer sur le descriptif  , manque accessoire , rayure, et emballage abimé .a sa réception , le carton abimé , manque sachet pour détartrage et aucune rayure ,la machine est neuve.donc je recommande cette machine très efficace et warehouse qu''il est tous aussimerci a amazon de m''avoir fait cette belle affaire.", "date": "2021-07-17T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 50, "title": "De’Longhi Dinamica Plus.", "body": "Bardzo solidny produkt. Kawa z ekspresu bardzo dobra. Prosta obsługa i łatwa konserwacja. Polecam.", "date": "2024-09-03T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 50, "title": "I just got this maching and its amazing", "body": "I had some doubt first when i bought this machine as its 4 years old but it does exactly what i need, easy connectivity, easy set up and it brow like pro. The machine provide a real expsspresso and it has so many option for many type of coffe. for me it save time and energy to make a good perfect expresso.The app also has so much recipes for making different type of hot and cold drink. The only thing i feel bad for is not buying this machine when it first came. Its the best coffee machine i had.", "date": "2023-12-24T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 10, "title": "Sijtig", "body": "Koffiezetmachine was stuk.", "date": "2023-12-01T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}]', 'J''en suis ravi, j''avais auparavant une Jura Ena 9, qui me faisait un bon café, mais aucune comparaison avec celle ci.Le café est plus chaud (température réglable), avec un vrai goût d''expresso, une belle mousse. Les possibilités sont énormes, et très judicieuses, telle la carafe | J''ai mis du temps avant de choisir cette machine et je ne suis pas déçu.Reçu rapidement. Très bien emballée, la machine parait solide et bien pensée.Elle prend de la place sur un plan de travail en profondeur. Moins large qu''un micro onde.Je passerais sur l''application smartphone | Bonjour. Je suis un très bon client Chez Amazon et je me suis dit pourquoi pas acheter La cafetière sur Amazon seconde main. De plus, j''ai lu que les produits seconde main étaient très bien vérifiés.Bref, je reçois le produit qui était déjà très sale et après un bon coup d''éponge', 'published') ON DUPLICATE KEY UPDATE name=VALUES(name), price_eur=VALUES(price_eur), rating=VALUES(rating), ratings_total=VALUES(ratings_total), bestsellers_rank=VALUES(bestsellers_rank), main_image_url=VALUES(main_image_url), images_json=VALUES(images_json), top_reviews_json=VALUES(top_reviews_json), summary_avis=VALUES(summary_avis), updated_at=NOW();
