INSERT INTO products (asin, slug, name, brand, model_number, type_cafetiere, description_long, price_eur, currency, rating, ratings_total, bestsellers_rank, bestsellers_cat, amazons_choice, color, material, capacity_l, dimensions_cm, weight_kg, main_image_url, images_json, specifications_json, features_json, top_reviews_json, summary_avis, status) VALUES ('B09BVH86BR', 'philips-saeco-granaroma-deluxe-machine-expresso-cafe-a-grain-connexion-wi-fi-18-specialites-de-cafe-ecran-tactile-intuitif-6-profils-utilisateur-broyeur-en-ceramique-sm6685-00-18-b', 'Saeco GranAroma Deluxe Machine Expresso - Café à Grain - Connexion Wi-Fi, 18 Spécialités de Café, Écran Tactile Intuitif, 6 Profils Utilisateur, Broyeur en Céramique (SM6685/00) 18 Boissons Acier Inoxydable', 'Philips', 'SM6685/00', 'espresso_broyeur_auto', 'Saeco GranAroma Deluxe Machine Expresso - Café à grain entièrement automatique, machine expresso avec mousseur à lait pour un café personnalisé à vos goûts. Profitez d''un contrôle total grâce à son interface intuitive sur écran tactile et personnalisez facilement votre café grâce aux préréglages de préférences intégrés. Vous n''aurez besoin ni d''un moulin à café ni d''un mousseur à lait - tout est intégré.', 752.69, 'EUR', 4, 842, 175, 'Machines à café automatiques', 1, 'Acier Inoxydable', 'Plastique', NULL, '44,8P x 26,2l x 38,3H centimètres', NULL, 'https://m.media-amazon.com/images/I/61rMviOJWTL.jpg', '[{"link": "https://m.media-amazon.com/images/I/61WAGmXpSPL._AC_SL1500_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61CcgHUPHKL._AC_SL1500_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61rpdN4JPLL._AC_SL1500_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61B6bEg65uL._AC_SL1500_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61Fe0xYZHaL._AC_SL1500_.jpg"}]', '[{"name": "Marque", "value": "Philips"}, {"name": "Capacité", "value": "1200 Millilitres"}, {"name": "Couleur", "value": "Acier Inoxydable"}, {"name": "Dimensions du produit", "value": "44,8P x 26,2l x 38,3H centimètres"}, {"name": "Caractéristique spéciale", "value": "Connectivité Wi-Fi"}, {"name": "Type de cafetière", "value": "Machine à espresso"}, {"name": "Matériau", "value": "Plastique"}, {"name": "Style", "value": "18 spécialités de café"}, {"name": "Usages spécifiques pour le produit", "value": "Cappuccino, Espresso"}, {"name": "Usages recommandés pour le produit", "value": "Voyage"}, {"name": "Caractéristiques spéciales", "value": "Connectivité Wi-Fi"}, {"name": "Usages particuliers du produit", "value": "Cappuccino, Espresso"}, {"name": "Mode de fonctionnement", "value": "Entièrement automatique"}, {"name": "Tension", "value": "230 Volts"}, {"name": "Entrée par interface homme-machine", "value": "Écran tactile"}, {"name": "Type de café", "value": "sol"}, {"name": "Source d’alimentation", "value": "courant alternatif (AC)"}, {"name": "Type de filtre", "value": "Réutilisable"}, {"name": "Dimensions de l''article P x L x H", "value": "44,8P x 26,2l x 38,3H centimètres"}, {"name": "Poids de l''article", "value": "11,44 Kilogrammes"}, {"name": "Nombre d’articles dans l''unité vendue au client", "value": "1"}, {"name": "Unité de comptage", "value": "1.0 unité"}, {"name": "taille_filtre_à_café", "value": "#2"}, {"name": "Composants inclus", "value": "Mousseur à lait, filtre AquaClean"}, {"name": "Nom du modèle", "value": "granaroma deluxe"}, {"name": "Numéro du modèle", "value": "SM6685/00"}, {"name": "Fabricant", "value": "Philips"}, {"name": "Référence de pièce", "value": "SM6685/00"}, {"name": "Nom du type du produit", "value": "machines à café automatiques"}, {"name": "Classement des meilleures ventes d''Amazon", "value": "325984 en Cuisine et Maison (Voir les 100 premiers en Cuisine et Maison) 175 en Machines à café automatiques"}, {"name": "ASIN", "value": "B09BVH86BR"}, {"name": "Moyenne des commentaires client", "value": "4,0    4,0 sur 5 étoiles         (842)           4,0 sur 5 étoiles"}, {"name": "Finitions extérieures", "value": "Revêtement en plastique"}, {"name": "L''article est-il lavable au lave-vaisselle ?", "value": "Non"}]', '["Contrôle simple : Wi-Fi intégré pour améliorer en permanence la préparation de vos Spécialités de Café et intégrer de nouvelles recettes, fonctionnalités et profiter des mises à jour logicielles, directement sur l''écran et sans avoir besoin d''une application mobile", "18 Spécialités de Café en toute simplicité : Découvrez tout un univers de café - Expresso, cappuccino, macchiato et toute une gamme d''options de spécialité - Enregistrez vos préférences jusqu''à 6 Profils utilisateur pour une sélection instantanée", "Personnalisez votre café : La fonction CoffeeMaestro vous permet de sélectionner le profil de goût souhaité - Ajuste automatiquement les paramètres de préparation comme l''intensité et le volume", "Obtenez des conseils interactifs pour une personnalisation automatisée : La fonction CoffeeEqualizer vous permet de personnaliser l''intensité, le café, le volume de lait, la température, le goût, la mousse et plus encore - Utilisez la fonction ExtraShot pour un café plus intense", "La connectivité de l''appareil est disponible dans les pays suivants : Allemagne, Autriche, Suisse, France, Belgique, Pays-Bas, Luxembourg, Italie, Hongrie, République tchèque, Croatie, Serbie, Pologne, Slovénie, Slovaquie, Roumanie, Lettonie, Lituanie, Estonie, Espagne, Portugal, Bulgarie. La fonctionnalité d''achat sur Amazon est disponible dans les pays suivants : France, Allemagne, Italie, Espagne", "AquaClean inclus : le filtre anti-calcaire innovant AquaClean vous permet de déguster jusqu''à 5000 tasses sans avoir besoin de détartrer."]', '[{"rating": 5, "title": null, "body": null, "date": "2022-01-31T00:00:00.000Z", "helpful_votes": 42, "verified_purchase": true}, {"rating": 5, "title": null, "body": null, "date": "Avis laissé en France le 19 février 2024Avis laissé en France le 19 février 2024", "helpful_votes": 3, "verified_purchase": true}, {"rating": 1, "title": null, "body": null, "date": "2022-12-08T00:00:00.000Z", "helpful_votes": 29, "verified_purchase": true}, {"rating": 5, "title": null, "body": null, "date": "Avis laissé en France le 4 septembre 2022Avis laissé en France le 4 septembre 2022", "helpful_votes": 35, "verified_purchase": true}, {"rating": 4, "title": null, "body": null, "date": "Avis laissé en France le 10 février 2022Avis laissé en France le 10 février 2022", "helpful_votes": 5, "verified_purchase": true}, {"rating": 5, "title": null, "body": null, "date": "2025-10-01T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 2, "title": null, "body": null, "date": "2025-10-02T00:00:00.000Z", "helpful_votes": 0, "verified_purchase": true}, {"rating": 5, "title": null, "body": null, "date": "Avis laissé en France le 17 mars 2022Avis laissé en France le 17 mars 2022", "helpful_votes": 0, "verified_purchase": true}, {"rating": 5, "title": null, "body": null, "date": "Avis laissé en Allemagne le 15 octobre 2023Avis laissé en Allemagne le 15 octobre 2023", "helpful_votes": 0, "verified_purchase": true}, {"rating": 2, "title": null, "body": null, "date": "Avis laissé aux Pays-Bas le 25 septembre 2022Avis laissé aux Pays-Bas le 25 septembre 2022", "helpful_votes": 0, "verified_purchase": true}]', NULL, 'published') ON DUPLICATE KEY UPDATE name=VALUES(name), price_eur=VALUES(price_eur), rating=VALUES(rating), ratings_total=VALUES(ratings_total), bestsellers_rank=VALUES(bestsellers_rank), main_image_url=VALUES(main_image_url), images_json=VALUES(images_json), top_reviews_json=VALUES(top_reviews_json), summary_avis=VALUES(summary_avis), updated_at=NOW();
INSERT INTO products (asin, slug, name, brand, model_number, type_cafetiere, description_long, price_eur, currency, rating, ratings_total, bestsellers_rank, bestsellers_cat, amazons_choice, color, material, capacity_l, dimensions_cm, weight_kg, main_image_url, images_json, specifications_json, features_json, top_reviews_json, summary_avis, status) VALUES ('B09CGSCBK5', 'de-longhi-de-longhi-magnifica-evo-machine-a-cafe-et-cappucino-avec-broyeur-a-grains-ecam292-33-sb-argent-exclusif-amazon-systeme-de-lait-manuel-argente', 'De''Longhi Magnifica Evo, Machine à Café et Cappucino avec Broyeur à Grains, ECAM292.33.SB, Argent [Exclusif Amazon] Système de Lait Manuel Argenté', 'De''Longhi', 'ECAM292.33.SB', 'espresso_broyeur_auto', 'De''Longhi Magnifica Evo, Machine expresso avec broyeur, ECAM292.33.SB, Argent - Créez des boissons personnalisées à base de lait et de café à partir de grains fraîchement moulus. 5 recettes à touche unique, dont café allongé et americano. Mousse de lait crémeuse grâce au mousseur à lait manuel. Grille lavable au lave-vaisselle et unité d''infusion amovible pour un nettoyage facile. Profitez de l''expérience ultime du café dans le confort de votre maison avec la De''Longhi Magnifica Evo. Préparez l''espresso parfait à partir de grains fraîchement moulus, l''une des 5 recettes disponibles d''une simple pression. Elle est dotée d''un écran tactile intuitif avec des icônes en couleur pour chaque recette. Sa finition élégante argentée et noire est le complément parfait de toute cuisine moderne.', 399.99, 'EUR', 4, 1842, 8, 'Machines à café automatiques', 1, 'Argent', 'Acier inoxydable', 1.8, '44P x 24l x 36H centimètres', NULL, 'https://m.media-amazon.com/images/I/61RNSUZrLLL.jpg', '[{"link": "https://m.media-amazon.com/images/I/71xW7tsk4vL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61XG5LbRl3L._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61EEVFGI99L._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/71w3rRfdM2L._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61ii1tf8g5L._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61rD5hdwWHL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61BFDmsiRoL._AC_SL1499_.jpg"}, {"link": "https://m.media-amazon.com/images/I/61xl+hblPSL._AC_SL1499_.jpg"}]', '[{"name": "Marque", "value": "De''Longhi"}, {"name": "Capacité", "value": "1,8 Litres"}, {"name": "Couleur", "value": "Argent"}, {"name": "Dimensions du produit", "value": "44P x 24l x 36H centimètres"}, {"name": "Caractéristique spéciale", "value": "Mousseur à lait"}, {"name": "Type de cafetière", "value": "Machine à espresso"}, {"name": "Matériau", "value": "Acier inoxydable"}, {"name": "Style", "value": "Panneau Tactile Coloré/5 Boissons"}, {"name": "Usages spécifiques pour le produit", "value": "milk_frother"}, {"name": "Usages recommandés pour le produit", "value": "Voyage"}, {"name": "Caractéristiques spéciales", "value": "Mousseur à lait"}, {"name": "Usages particuliers du produit", "value": "milk_frother"}, {"name": "Mode de fonctionnement", "value": "Entièrement automatique"}, {"name": "Puissance", "value": "1450 Watts"}, {"name": "Tension", "value": "230 Volts"}, {"name": "Entrée par interface homme-machine", "value": "Boutons"}, {"name": "Type de café", "value": "haricots entiers"}, {"name": "Source d’alimentation", "value": "Adaptateur secteur"}, {"name": "Type de filtre", "value": "Réutilisable"}, {"name": "Dimensions de l''article P x L x H", "value": "44P x 24l x 36H centimètres"}, {"name": "Poids de l''article", "value": "11,7 Kilogrammes"}, {"name": "Nombre d’articles dans l''unité vendue au client", "value": "1"}, {"name": "Disponibilité de pièces détachées", "value": "10 Ans"}, {"name": "Pays d’origine", "value": "Roumanie"}, {"name": "Numéro du modèle", "value": "ECAM292.33.SB"}, {"name": "Année de fabrication", "value": "2022"}, {"name": "Fabricant", "value": "De''Longhi"}, {"name": "Référence de pièce"